var SNAPSHOT_DIR = path4.join(process.cwd(), "data");
var SNAPSHOT_FILE = path4.join(SNAPSHOT_DIR, "firestore-knowledge-snapshot.json");
function computeRecordsHash(records) {
  if (records.length === 0) return "fs_empty_0";
  let hashStr = "";
  for (const r of records) {
    hashStr += `${r.id}|${r.topic}|${r.answer}|${r.approved}|${r.version}|${r.updatedAt};`;
  }
  let hash = 0;
  for (let i = 0; i < hashStr.length; i++) {
    const char = hashStr.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash |= 0;
  }
  return "fs_" + Math.abs(hash).toString(16) + "_" + records.length;
}
