function initPerformanceStorage() {
  try {
    if (!fs5.existsSync(DATA_DIR3)) {
      fs5.mkdirSync(DATA_DIR3, { recursive: true });
    }
    if (fs5.existsSync(PERF_FILE)) {
      const raw = fs5.readFileSync(PERF_FILE, "utf-8");
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed) && parsed.length > 0) {
        for (const item of parsed) {
          if (item && item.id) {
            perfCache.set(item.id, item);
          }
        }
      }
    }
    for (const item of SEED_PERFORMANCE) {
      if (!perfCache.has(item.id)) {
        perfCache.set(item.id, item);
      }
    }
    for (const item of AUGUST_2026_PERFORMANCE) {
      perfCache.set(item.id, item);
    }
    persistToDisk2();
  } catch (err) {
    console.warn("[PerformanceService] Storage init error:", err);
    for (const item of SEED_PERFORMANCE) {
      perfCache.set(item.id, item);
    }
    for (const item of AUGUST_2026_PERFORMANCE) {
      perfCache.set(item.id, item);
    }
  }
}
