        title: "\u0627\u0644\u0627\u0633\u062A\u0641\u0633\u0627\u0631\u0627\u062A \u0627\u0644\u0645\u0639\u0644\u0642\u0629 (Unanswered Inquiries)",
        description: "\u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u0627\u0644\u062A\u064A \u0644\u0645 \u062A\u062C\u062F \u0625\u062C\u0627\u0628\u0629 \u0645\u0628\u0627\u0634\u0631\u0629 \u0644\u062A\u062D\u0633\u064A\u0646 \u0648\u062A\u0648\u0633\u064A\u0639 \u0642\u0627\u0639\u062F\u0629 \u0627\u0644\u0645\u0639\u0631\u0641\u0629",
        icon: "HelpCircle",
