    details: `\u0625\u0639\u0627\u062F\u0629 \u0641\u062A\u062D \u0627\u0644\u0643\u0634\u0641 \u0644\u0644\u0645\u0631\u0627\u062C\u0639\u0629 \u0648\u0627\u0644\u062A\u0639\u062F\u064A\u0644 (\u0627\u0644\u0625\u0635\u062F\u0627\u0631 ${dataset.version}). \u0627\u0644\u0633\u0628\u0628: ${reason || "\u0645\u0631\u0627\u062C\u0639\u0629 \u0648\u062A\u062D\u062F\u064A\u062B"}`
