  if (!emp) throw new Error(`\u0627\u0644\u0645\u0648\u0638\u0641 "${unknownUsername}" \u063A\u064A\u0631 \u0645\u0648\u062C\u0648\u062F \u0641\u064A \u0643\u0634\u0641 \u0634\u0647\u0631 ${monthKey}.`);
